/**
 * Coverage figures for the generated command surface.
 *
 * Every number here is transcribed from the committed Discovery index at
 * `src/discovery/manifest.json` (generated by `scripts/fetch-discovery.ts`),
 * which is what `grr api list` reads at runtime. Revisions are the
 * `discoveryRevision` each service document reported when it was last
 * refreshed, so a stale row here means the index moved, not that the docs
 * drifted.
 *
 * Every service has dedicated `grr <service>` commands — the tree is
 * generated from the index, so the ten namespaces are on equal footing and
 * `grr api` is the flat, id-based way into the same methods.
 */
export interface DiscoveryService {
  /** Key accepted by `grr api list --service` and the `grr api call` id prefix. */
  name: string;
  /** Human label used in prose. */
  label: string;
  /** Google API version this index was distilled from. */
  version: string;
  methods: number;
  /** Distinct scopes declared across the service's methods. */
  scopes: number;
  /** `revision` field of the Discovery document at refresh time. */
  revision: string;
  /** One-line note on what the service covers. */
  note: string;
}

